    {
      "@type": "FAQPage",
      "@id": "https://www.data4thepeople.com/p/substance-use-treatment-viz#faq",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "How many people in the U.S. have a substance use disorder?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "SAMHSA estimates 48.4 million people 12 and older in 2023-2024, or 16.9%. This uses the newer DSM-5 definition, so it cannot be compared with estimates from 2020 or earlier."
          }
        },
        {
          "@type": "Question",
          "name": "Which state has the highest rate of substance use disorder?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In 2023-2024, the District of Columbia had the highest rate, 23.8% of people 12 and older, followed by Maine and Colorado (22.4%). Utah had the lowest, 12.6%."
          }
        },
        {
          "@type": "Question",
          "name": "Why did the number of people with a substance use disorder more than double in 2022?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "SAMHSA changed its survey and its definition of a disorder starting in 2021. SAMHSA says the estimates from 2021 on are not comparable with earlier years, so the jump should not be read as a change in how many people had a disorder."
          }
        },
        {
          "@type": "Question",
          "name": "Which state has the fewest treatment workers for the people who need them?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In 2024, Nevada had the most people with SUD per treatment worker, 177, followed by Alabama (175) and Georgia (162). Massachusetts had the fewest, 49."
          }
        },
        {
          "@type": "Question",
          "name": "What counts as a treatment worker?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Substance use and mental health counselors, plus mental health and substance use social workers, as counted by the Bureau of Labor Statistics. It includes every work setting. It does not include doctors, nurses, peer support workers or the self-employed."
          }
        },
        {
          "@type": "Question",
          "name": "Which state has the fewest treatment facilities per person?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In 2024, Texas had the fewest outpatient substance use treatment establishments for its population, 1.6 per 100,000 residents, followed by South Carolina (1.7) and Alabama (2.2). Kentucky had the most, 11.4."
          }
        },
        {
          "@type": "Question",
          "name": "Which state has the highest overdose and alcohol death rate?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In 2024, Alaska and New Mexico, at 73.8 deaths per 100,000 residents."
          }
        },
        {
          "@type": "Question",
          "name": "Why is my state gray?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The source did not publish a number for that state and year. We leave it blank and do not estimate one."
          }
        },
        {
          "@type": "Question",
          "name": "Why are some years missing from the SUD map?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "SAMHSA published no state estimates for the survey windows ending in 2002, 2015, 2020 and 2021."
          }
        },
        {
          "@type": "Question",
          "name": "Where can I find treatment?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Call or text 988 for the Suicide & Crisis Lifeline, or search FindTreatment.gov, SAMHSA's treatment locator, by ZIP code."
          }
        },
        {
          "@type": "Question",
          "name": "Where does the data come from?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "SAMHSA's National Survey on Drug Use and Health and its treatment facility surveys, the Bureau of Labor Statistics' Occupational Employment and Wage Statistics, and CDC WONDER death records."
          }
        },
        {
          "@type": "Question",
          "name": "Is the map free to use?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. It is free to use and needs no sign-in."
          }
        }
